async function refreshLegacyNotifierHooksIfNeeded(notifierPaths) {
    if (!notifierPaths.tokiBin)
        return;
    try {
        const result = await migrateLegacyNotifiers(notifierPaths);
        if (!result.changed)
            return;
        const sources = result.hooks
            .filter((hook) => hook.changed)
            .map((hook) => hook.source);
        if (sources.length > 0) {
            log.info(`Updated legacy notifier hooks for: ${sources.join(", ")}.`);
        }
        else {
            log.info("Refreshed legacy notify handler.");
        }
    }
    catch (error) {
        const detail = error instanceof Error ? error.message : String(error);
        log.warn(`Legacy notifier hook migration skipped: ${detail}`);
    }
}
async function loadVscodeCopilotAgentSessionIds(dbPaths) {
    const sessionIds = new Set();
    let available = true;
    for (const dbPath of dbPaths) {
        const result = await readVscodeCopilotAgentSessionIdsFromFile(dbPath);
        if (result.kind === "compatible") {
            for (const sessionId of result.sessionIds) {
                sessionIds.add(sessionId);
            }
        }
        else if (result.kind === "failure") {
            available = false;
            const detail = result.detail ? `: ${result.detail}` : "";
            log.warn(`VS Code Agent Host attribution unavailable (${result.reason})${detail}`);
        }
    }
    return { sessionIds, available };
}
