async function warnIfLegacyNotifierHooks(notifierPaths) {
    if (!notifierPaths.tokiBin)
        return;
    try {
        const { notifyHandlerNeedsRefresh, sources } = await detectLegacyNotifiers(notifierPaths);
        if (!notifyHandlerNeedsRefresh && sources.length === 0)
            return;
        const subject = sources.length > 0
