            : "Legacy notify handler detected.";
        log.warn(`${subject} Run ${pc.cyan("toki init")} or ${pc.cyan("toki sync")} to refresh them.`);
    }
    catch {
        // Detection is best-effort — stay silent if the check itself fails.
    }
}
